css:
.marker{display:inline-block; background:#a9f0a0; border-radius:2px; padding:.35em 1em; transform:rotate(-2.5deg); font-weight:700}
.on-line{display:inline-block; transform:rotate(-17deg); transform-origin:left bottom}
.on-line b{display:block; font-size:26px; color:#00a5b5}
.on-line span{font-size:14px; color:#4a3a35}
.focus{display:flex; justify-content:center; gap:6px; margin-bottom:4px}
.focus i{width:2px; height:12px; background:#0a93a8; display:block}
.focus i:first-child{transform:rotate(22deg)}
.focus i:last-child{transform:rotate(-22deg)}
